with remaining_keys as (select manager_id, dept_id from employees except all select manager_id, dept_id from employees where level = 'L3'), verified as (select s.* from employees s join remaining_keys k on s.manager_id = k.manager_id and s.dept_id = k.dept_id) select s.id, s.email, s.dept_id, s.manager_id, s.job_title, s.salary, s.is_remote, s.level, case when job_title rlike '^(Director|Analyst)$' then 'GROUP_B' when job_title rlike '^(Engineer|Manager)$' then 'PRIORITY' else 'CORE' end as job_title_zone, (select avg(t2.salary) from employees t2 where t2.dept_id = s.dept_id) as avg_employee_salary from verified s;
